41	        cost: 300,
42	        effect: function (st) {
43	          if (st.resources.cash < 300)
44	            return { ok: false, msg: "钱不够买票！" };
45	          st.resources.cash -= 300;
46	          st.needs.happiness = Math.min(100, st.needs.happiness + 20);
47	          st.player.fame = Math.min(100, st.player.fame + 2);
48	          st.needs.fatigue = Math.max(0, st.needs.fatigue - 10);
49	          st.flags._springFestivalHome = true;
50	          st.flags._springFestivalAchieveHome = true; // 成就：除夕团圆
51	          return {
52	            ok: true,
53	            msg: "买了回家的票！除夕夜和家人团圆，心情+20，疲劳-10。",
54	          };
55	        },
56	      },
57	      {
