62	          st.needs.hunger = Math.min(100, st.needs.hunger + 30);
63	          st.needs.happiness = Math.max(0, st.needs.happiness - 5);
64	          st.flags._springFestivalAlone = true;
65	          return {
66	            ok: true,
67	            msg: "花¥30买了点食材，自己煮了一顿年夜饭。虽然简单，但也算过年。",
68	          };
69	        },
70	      },
