956	  if (!f) return null;
957	  if (typeof NPCS === "undefined") return null;
958	  for (var i = 0; i < NPCS.length; i++) {
959	    var npc = NPCS[i];
960	    if (npc.id !== npcId) continue;
961	    if (!npc.festivalLines) return null;
962	    var line = npc.festivalLines[f.id];
963	    return line || null;
964	  }
965	  return null;
966	}
967	
968	/** 获取节日价格修正说明文本（用于交易界面提示） */
969	function getFestivalPriceNote(state) {
970	  // 余震清仓期提示
971	  if (isShoppingClearancePeriod(state)) {
972	    var daysLeft2 = state.flags._shoppingClearanceEndDay - state.player.day;
973	    return (
974	      "📉 剁手节清仓（还剩" +
975	      daysLeft2 +
976	      "天）：日用品-18%, 服装-22%, 电子-20%（进货好时机）"
977	    );
978	  }
979	  var f = getCurrentFestival(state.player.day);
980	  if (!f || !f.priceMods) return "";
981	  var doy = state.player.day % 365;
982	  var daysLeft = f.startDay + f.duration - doy;
983	  var parts = [];
984	  Object.keys(f.priceMods).forEach(function (cat) {
985	    var mod = f.priceMods[cat];
986	    var pct = Math.round((mod - 1) * 100);
987	    parts.push(getFestivalCategoryName(cat) + (pct > 0 ? "+" : "") + pct + "%");
988	  });
989	  return (
990	    f.icon + " " + f.name + "（还剩" + daysLeft + "天）：" + parts.join("，")
991	  );
992	}
993	
994	// ====== 春节7天特殊活动调度 ======
995	
996	/**
997	 * 获取春节当天的特殊活动（如果当天有）
998	 * @param {number} dayOffset - 春节内的天偏移（0=除夕，1=初一，...6=初六）
999	 * @returns {Object|null} 活动定义或null
1000	 */
1001	function getSpringFestivalEvent(dayOffset) {
1002	  for (var i = 0; i < SPRING_FESTIVAL_EVENTS.length; i++) {
1003	    if (SPRING_FESTIVAL_EVENTS[i].dayOffset === dayOffset) {
1004	      return SPRING_FESTIVAL_EVENTS[i];
1005	    }
1006	  }
1007	  return null;
1008	}
1009	
1010	/**
1011	 * 检查并触发春节特殊活动
1012	 * 在每日结算时调用（DAILY_PIPELINE）
1013	 */
1014	function checkSpringFestivalEvents(state) {
1015	  var f = getCurrentFestival(state.player.day);
1016	  if (!f || f.id !== "spring_festival") return;
1017	
1018	  var doy = state.player.day % 365;
1019	  var dayOffset = doy - f.startDay; // 0-6
1020	
1021	  if (dayOffset < 0 || dayOffset > 6) return;
1022	
1023	  var year = Math.floor(state.player.day / 365);
1024	  var flagKey = "_springFestEvent_" + dayOffset + "_y" + year;
1025	
1026	  if (state.flags[flagKey]) return; // 已触发过
1027	
1028	  var eventDef = getSpringFestivalEvent(dayOffset);
1029	  if (!eventDef) return;
1030	
1031	  state.flags[flagKey] = true;
1032	
1033	  // 调度为待弹事件
1034	  state._pendingEvent = {
1035	    id: "spring_fest_day" + dayOffset,
1036	    phase: state.player.phase,
1037	    icon: eventDef.icon,
1038	    title: eventDef.title,
1039	    story: eventDef.desc,
1040	    choices: eventDef.choices,
1041	    _isSpringFestivalEvent: true,
1042	  };
1043	  state._pendingEventId = "spring_fest_day" + dayOffset;
1044	
1045	  // 延迟弹窗
1046	  setTimeout(function () {
1047	    var s = StateManager.getState();
1048	    if (
1049	      s._pendingEvent &&
1050	      s._pendingEventId === "spring_fest_day" + dayOffset
1051	    ) {
1052	      if (typeof showEventModal === "function") {
1053	        showEventModal(s._pendingEvent);
1054	      }
1055	      if (typeof playSound === "function") playSound("event");
1056	    }
1057	  }, 50);
1058	
1059	  StateManager.addMessage(
1060	    eventDef.icon + " 【春节第" + (dayOffset + 1) + "天】" + eventDef.title,
1061	    "event",
1062	  );
1063	
1064	  // 追踪春节参与天数（用于成就：春节全勤）
1065	  var participatedKey = "_springFestDaysParticipated_y" + year;
1066	  if (!state.flags[participatedKey]) {
1067	    state.flags[participatedKey] = 0;
1068	  }
1069	  state.flags[participatedKey] = Math.min(
1070	    7,
1071	    (state.flags[participatedKey] || 0) + 1,
1072	  );
1073	  if (state.flags[participatedKey] >= 7) {
1074	    state.flags._springFestivalAchieveFullAttendance = true; // 成就：春节全勤
1075	  }
1076	}
1077	
1078	// ====== 季节性价格波动 ======
1079	
1080	/**
1081	 * 获取当前季节的价格修正
1082	 * @param {Object} state - 游戏状态
1083	 * @returns {Object} 价格修正对象
1084	 */
1085	function getSeasonalPriceMod(state) {
1086	  var season = getCurrentSeason(state.player.day);
1087	  if (!season) return {};
1088	  return SEASONAL_PRICE_MODS[season.id] || {};
1089	}
1090	
1091	/**
1092	 * 获取商品分类的综合价格修正（节日 + 季节）
1093	 * @param {Object} state - 游戏状态
1094	 * @param {string} category - 商品分类
1095	 * @returns {number} 综合价格修正乘数
1096	 */
1097	function getCombinedPriceMod(state, category) {
1098	  var mod = 1.0;
1099	
1100	  // 节日修正
1101	  var festMod = getFestivalPriceMod(state, category);
1102	  mod *= festMod;
1103	
1104	  // 季节修正
1105	  var seasonMod = getSeasonalPriceMod(state)[category];
1106	  if (seasonMod) {
1107	    mod *= seasonMod;
1108	  }
1109	
1110	  return mod;
1111	}
1112	
1113	/**
1114	 * 获取季节名称
1115	 */
1116	function getSeasonName(day) {
1117	  var season = getCurrentSeason(day);
1118	  return season ? season.name : "冬季";
1119	}
1120	
1121	/**
1122	 * 获取季节图标
1123	 */
1124	function getSeasonIcon(day) {
1125	  var season = getCurrentSeason(day);
1126	  return season ? season.icon : "❄️";
1127	}
1128	
1129	/**
1130	 * 获取季节描述
1131	 */
1132	function getSeasonDesc(day) {
1133	  var season = getCurrentSeason(day);
1134	  if (!season) return "寒冬腊月";
1135	  var descs = {
1136	    spring: "春暖花开，万物复苏",
1137	    summer: "烈日炎炎，酷暑难耐",
1138	    autumn: "秋高气爽，丹桂飘香",
1139	    winter: "寒风凛冽，岁末年终",
1140	  };
1141	  return descs[season.id] || "";
1142	}
1143	
1144	// ====== 节日/季节综合提示 ======
1145	
1146	/**
1147	 * 获取当前节日+季节的综合提示文本（用于UI展示）
1148	 */
1149	function getSeasonFestivalTip(state) {
1150	  var season = getCurrentSeason(state.player.day);
1151	  var festival = getCurrentFestival(state.player.day);
1152	
1153	  var parts = [];
1154	
1155	  if (season) {
1156	    parts.push(
1157	      season.icon + " " + season.name + "：" + getSeasonDesc(state.player.day),
1158	    );
1159	  }
1160	
1161	  if (festival) {
1162	    parts.push(
1163	      festival.icon +
1164	        " " +
1165	        festival.name +
1166	        "（还剩" +
1167	        (festival.startDay + festival.duration - (state.player.day % 365)) +
1168	        "天）",
1169	    );
1170	  }
1171	
1172	  // 季节性价格提示
1173	  var seasonMods = getSeasonalPriceMod(state);
1174	  var hotBuy = [];
1175	  var hotSell = [];
1176	  for (var cat in seasonMods) {
1177	    var catName = getFestivalCategoryName(cat);
1178	    if (seasonMods[cat] < 0.9) {
1179	      hotBuy.push(catName);
1180	    } else if (seasonMods[cat] > 1.1) {
1181	      hotSell.push(catName);
1182	    }
1183	  }
1184	
1185	  if (hotBuy.length > 0) {
1186	    parts.push("💡 进货好时机：" + hotBuy.join("、") + "降价中");
1187	  }
1188	  if (hotSell.length > 0) {
1189	    parts.push("💡 卖出好时机：" + hotSell.join("、") + "涨价中");
1190	  }
1191	
1192	  return parts.join(" | ");
1193	}
